import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as a,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何用 Linux 命令行发电子邮件 | LCTT x X-CMD","titleTemplate":false,"description":"如何用 Linux 命令行发电子邮件 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用 Linux 命令行发电子邮件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用 Linux 命令行发电子邮件 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190614 How to send email from the Linux command line","title":"如何用 Linux 命令行发电子邮件","tag":"201906","desc":""},"relativePath":"201906/20190614 How to send email from the Linux command line.md","filePath":"[post].md"}'),c={name:"201906/20190614 How to send email from the Linux command line.md"};function h(g,s,u,k,m,b){const e=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何用-linux-命令行发电子邮件" tabindex="-1">如何用 Linux 命令行发电子邮件 <a class="header-anchor" href="#如何用-linux-命令行发电子邮件" aria-label="Permalink to “如何用 Linux 命令行发电子邮件”">​</a></h1><blockquote><p>Linux 提供了几个可以让你通过终端发送电子邮件的命令，下面来展示一些有趣的方法。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2017/08/email_image_blue-100732096-large.jpg" alt="Molnia/iStock"></p><p>Linux 可以用多种方式通过命令行发送电子邮件。有一些方法十分简单，有一些相对会复杂一些，不过仍旧提供了很多有用的特性。选择哪一种方式取决于你想要什么 —— 向同事快速发送消息，还是向一批人群发带有附件的更复杂的信息。接下来看一看几种可行方案：</p><h3 id="mail" tabindex="-1">mail <a class="header-anchor" href="#mail" aria-label="Permalink to “mail”">​</a></h3><p>发送一条简单消息最便捷的 Linux 命令是 <code>mail</code>。假设你需要提醒老板你今天得早点走，你可以使用这样的一条命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Reminder: Leaving at 4 PM today&quot; | mail -s &quot;early departure&quot; myboss</span></span></code></pre></div><p>另一种方式是从一个文件中提取出你想要发送的文本信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mail -s &quot;Reminder:Leaving early&quot; myboss &lt; reason4leaving</span></span></code></pre></div><p>在以上两种情况中，你都可以通过 <code>-s</code> 来为邮件添加标题。</p><h3 id="sendmail" tabindex="-1">sendmail <a class="header-anchor" href="#sendmail" aria-label="Permalink to “sendmail”">​</a></h3><p>使用 <code>sendmail</code> 命令可以发送一封不包含标题的快信。（用目标收件人替换 <code>recip</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;leaving now&quot; | sendmail recip</span></span></code></pre></div><p>你可以用这条命令发送一条只有标题，没有内容的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Subject: leaving now&quot; | sendmail recip</span></span></code></pre></div><p>你也可以用 <code>sendmail</code> 发送一条包含一条标题行的完整信息。不过使用这个方法时，你的标题行会被添加到要发送的文件中，如下例所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Subject: Requested lyrics</span></span>
<span class="line"><span>I would just like to say that, in my opinion, longer hair and other flamboyant</span></span>
<span class="line"><span>affectations of appearance are nothing more ...</span></span></code></pre></div><p>你也可以发送这样的文件（<code>lyric</code> 文件包含标题和正文）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sendmail recip &lt; lyrics</span></span></code></pre></div><p><code>sendmain</code> 的输出也可以很冗长。如果你感到好奇并希望查看发送系统和接收系统之间的交互，请添加 <code>-v</code> （verbose）选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sendmail -v recip@emailsite.com &lt; lyrics</span></span></code></pre></div><h3 id="mutt" tabindex="-1">mutt <a class="header-anchor" href="#mutt" aria-label="Permalink to “mutt”">​</a></h3><p><code>mutt</code> 是通过命令行发送邮件的一个很好的工具，在使用前你需要安装它。<code>mutt</code> 的一个很方便的优势就是它允许你在邮件中添加附件。</p><p>使用 <code>mutt</code> 发送一条快速信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Please check last night&#39;s backups&quot; | mutt -s &quot;backup check&quot; recip</span></span></code></pre></div><p>从文件中获取内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mutt -s &quot;Agenda&quot; recip &lt; agenda</span></span></code></pre></div><p>使用 <code>-a</code> 选项在 <code>mutt</code> 中添加附件。你甚至可以添加不止一个附件 —— 如下一条命令所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mutt -s &quot;Agenda&quot; recip -a agenda -a speakers &lt; msg</span></span></code></pre></div><p>在以上的命令中，<code>msg</code> 文件包含了邮件中的正文。如果你没有其他补充的内容，你可以这样来代替之前的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;&quot; | mutt -s &quot;Agenda&quot; recip -a agenda -a speakers</span></span></code></pre></div><p><code>mutt</code> 另一个有用的功能是可以添加抄送（<code>-c</code>）和密送（<code>-b</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mutt -s &quot;Minutes from last meeting&quot; recip@somesite.com -c myboss &lt; mins</span></span></code></pre></div><h3 id="telnet" tabindex="-1">telnet <a class="header-anchor" href="#telnet" aria-label="Permalink to “telnet”">​</a></h3><p>如果你想深入了解发送电子邮件的细节，你可以使用 <code>telnet</code> 来进行电子邮件交互操作。但正如所说的那样，你需要“学习术语”。邮件服务器期望一系列命令，其中包括自我介绍（<code>EHLO</code> 命令）、提供发件人（<code>MAIL FROM</code> 命令）、指定收件人（<code>RCPT TO</code> 命令），然后添加消息（<code>DATA</code>）并以 <code>.</code> 结束消息。并不是所有的电子邮件服务器都会响应这些请求。此方法通常仅用于故障排除。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ telnet emailsite.org 25</span></span>
<span class="line"><span>Trying 192.168.0.12...</span></span>
<span class="line"><span>Connected to emailsite.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>220 localhost ESMTP Sendmail 8.15.2/8.15.2/Debian-12; Wed, 12 Jun 2019 16:32:13 -0400; (No UCE/UBE) logging access from: mysite(OK)-mysite [192.168.0.12]</span></span>
<span class="line"><span>EHLO mysite.org                &lt;== introduce yourself</span></span>
<span class="line"><span>250-localhost Hello mysite [127.0.0.1], pleased to meet you</span></span>
<span class="line"><span>250-ENHANCEDSTATUSCODES</span></span>
<span class="line"><span>250-PIPELINING</span></span>
<span class="line"><span>250-EXPN</span></span>
<span class="line"><span>250-VERB</span></span>
<span class="line"><span>250-8BITMIME</span></span>
<span class="line"><span>250-SIZE</span></span>
<span class="line"><span>250-DSN</span></span>
<span class="line"><span>250-ETRN</span></span>
<span class="line"><span>250-AUTH DIGEST-MD5 CRAM-MD5</span></span>
<span class="line"><span>250-DELIVERBY</span></span>
<span class="line"><span>250 HELP</span></span>
<span class="line"><span>MAIL FROM: me@mysite.org       &lt;== 指定发件人</span></span>
<span class="line"><span>250 2.1.0 shs@mysite.org... Sender ok</span></span>
<span class="line"><span>RCPT TO: recip             &lt;== 指定收件人</span></span>
<span class="line"><span>250 2.1.5 recip... Recipient ok</span></span>
<span class="line"><span>DATA                   &lt;== 邮件内容开始</span></span>
<span class="line"><span>354 Enter mail, end with &quot;.&quot; on a line by itself</span></span>
<span class="line"><span>This is a test message. Please deliver it for me.</span></span>
<span class="line"><span>.                  &lt;== 内容结束</span></span>
<span class="line"><span>250 2.0.0 x5CKWDds029287 Message accepted for delivery</span></span>
<span class="line"><span>quit                   &lt;== 结束交互</span></span></code></pre></div><h3 id="向多个收件人发送电子邮件" tabindex="-1">向多个收件人发送电子邮件 <a class="header-anchor" href="#向多个收件人发送电子邮件" aria-label="Permalink to “向多个收件人发送电子邮件”">​</a></h3><p>如果你希望通过 Linux 命令行向一大组收件人发送电子邮件，你可以使用一个循环来帮助你完成任务，如下面应用在 <code>mutt</code> 中的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for recip in \`cat recips\`</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    mutt -s &quot;Minutes from May meeting&quot; $recip &lt; May_minutes</span></span>
<span class="line"><span>done</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>有很多方法可以从 Linux 命令行发送电子邮件。有些工具提供了相当多的选项。</p><hr>`,42)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://www.networkworld.com/article/3402027/how-to-send-email-from-the-linux-command-line.html"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3402027/how-to-send-email-from-the-linux-command-line.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),i(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),i(e,{href:"https://github.com/Modrisco"},{default:n(()=>[...s[4]||(s[4]=[a("Modrisco",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=l(c,[["render",h]]);export{x as __pageData,C as default};
